pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta es un array", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.be.an('array');
});

pm.test("Ningun psicologo expone correo o telefono", function () {
    const jsonData = pm.response.json();
    jsonData.forEach(function (psicologo) {
        pm.expect(psicologo).to.not.have.property('correo');
        pm.expect(psicologo).to.not.have.property('telefono');
    });
});

pm.test("Cada psicologo tiene los campos publicos esperados", function () {
    const jsonData = pm.response.json();
    jsonData.forEach(function (psicologo) {
        pm.expect(psicologo).to.have.property('id');
        pm.expect(psicologo).to.have.property('nombres');
        pm.expect(psicologo).to.have.property('apellidos');
    });
});

pm.test("Psicologo recibe 403 al intentar acceder al directorio", function () {
    pm.response.to.have.status(403);
});

pm.test("Solicitud creada exitosamente (201)", function () {
    pm.response.to.have.status(201);
});

pm.test("La respuesta incluye el estado pendiente", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data.estado).to.eql("pendiente");
});

pm.test("Rechaza solicitud duplicada (400)", function () {
    pm.response.to.have.status(400);
});

pm.test("Mensaje indica solicitud pendiente existente", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.message.toLowerCase()).to.include("pendiente");
});

pm.test("Rechaza autoasignacion (400)", function () {
    pm.response.to.have.status(400);
});

pm.test("Mensaje indica que no puede autoasignarse", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.message.toLowerCase()).to.include("mismo");
});

pm.test("Body invalido devuelve 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Mensaje indica datos invalidos", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.message.toLowerCase()).to.include("inv");
});

pm.test("Historial propio devuelve 200", function () {
    pm.response.to.have.status(200);
});

pm.test("El historial contiene al menos una solicitud", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data).to.be.an('array');
    pm.expect(jsonData.data.length).to.be.above(0);
});

pm.test("Historial de otro estudiante devuelve 200", function () {
    pm.response.to.have.status(200);
});

pm.test("El historial esta vacio (no ve solicitudes ajenas)", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data).to.be.an('array').that.is.empty;
});

pm.test("Ya tiene asignacion aprobada devuelve 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Mensaje indica asignacion activa existente", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.message.toLowerCase()).to.include("activa");
});
